# ============================================================
# AEGIS NIDS - STEP 7: Correlation Layer
# ============================================================
# Wires XDR Correlator with Detection Integration layer:
#   - Every DetectionContext is also submitted to XDR
#   - Events with same session_id link into cross-tier incidents
#   - Network attack + host process spawn + file write = one incident
#   - Incident severity escalates as new events arrive
#   - processEventWithCorrelation() runs full pipeline in one call
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 7 - Correlation Layer"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
        Write-Host "  [MKDIR] Created: $Dir"
    }
    $BackupPath = "$FullPath.step7_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/correlation_integration.zig (correlation_integration.zig, 593 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/correlation_integration.zig" -ExpectedLines 593 -Base64Content $B64_1
Write-Host ""

# File 2: core/nids_analyze.zig (nids_analyze.zig, 2310 lines)
$B64_2 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2310 -Base64Content $B64_2
Write-Host ""

# File 3: core/nids_main.zig (nids_main.zig, 257 lines)
$B64_3 = ''
Deploy-File -RelativePath "core/nids_main.zig" -ExpectedLines 257 -Base64Content $B64_3
Write-Host ""

# File 4: build.zig (build.zig, 84 lines)
$B64_4 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 84 -Base64Content $B64_4
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) {
    Write-Host "[BUILD] FAILED (exit $buildExit)"
    exit 1
}
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test (uses ErrorActionPreference=Continue)..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

Write-Host "============================================================"
